import { NextResponse } from 'next/server';

function extractDriveId(url: string): string {
  const match = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/id=([a-zA-Z0-9_-]+)/);
  return match ? match[1] : url;
}

export async function POST(req: Request) {
  try {
    const { movieDetail, versions, primaryDriveUrl } = await req.json();

    const GITHUB_TOKEN = process.env.GITHUB_TOKEN;
    const REPO_OWNER = process.env.GITHUB_REPO_OWNER;
    const REPO_NAME = process.env.GITHUB_REPO_NAME;
    const WORKER_BASE = process.env.CLOUDFLARE_WORKER_BASE || 'https://gdrive-stream.moinudeentv.workers.dev/?id=';

    const headers = {
      Authorization: `Bearer ${GITHUB_TOKEN}`,
      Accept: 'application/vnd.github.v3+json',
      'User-Agent': 'MoinuFlix-Admin-NextJS',
    };

    const primaryId = extractDriveId(primaryDriveUrl);
    const primaryStreamUrl = `${WORKER_BASE}${primaryId}`;

    const formattedVersions = versions.map((v: any) => ({
      ...v,
      stream_url: `${WORKER_BASE}${extractDriveId(v.drive_url)}`,
    }));

    const cleanMovieId = movieDetail.title
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '-')
      .replace(/-+/g, '-') + `-${movieDetail.year}`;

    const catalogRes = await fetch(
      `https://api.github.com/repos/${REPO_OWNER}/${REPO_NAME}/contents/catalog.json`,
      { headers }
    );
    const catalogData = await catalogRes.json();
    const catalogContent = JSON.parse(Buffer.from(catalogData.content, 'base64').toString('utf-8'));

    const currentChunkIndex = Math.floor(catalogContent.length / 50) + 1;
    const chunkFileName = `chunks/chunk_${String(currentChunkIndex).padStart(2, '0')}.json`;

    let chunkSha: string | undefined;
    let chunkMovies: any[] = [];
    try {
      const chunkRes = await fetch(
        `https://api.github.com/repos/${REPO_OWNER}/${REPO_NAME}/contents/${chunkFileName}`,
        { headers }
      );
      if (chunkRes.ok) {
        const chunkData = await chunkRes.json();
        chunkSha = chunkData.sha;
        const parsed = JSON.parse(Buffer.from(chunkData.content, 'base64').toString('utf-8'));
        chunkMovies = parsed.movies || [];
      }
    } catch (e) {}

    const fullDetail = {
      ...movieDetail,
      id: cleanMovieId,
      versions: formattedVersions,
      stream_url: primaryStreamUrl,
    };

    chunkMovies.push(fullDetail);

    await fetch(`https://api.github.com/repos/${REPO_OWNER}/${REPO_NAME}/contents/${chunkFileName}`, {
      method: 'PUT',
      headers,
      body: JSON.stringify({
        message: `Add ${movieDetail.title} to ${chunkFileName}`,
        content: Buffer.from(JSON.stringify({ movies: chunkMovies }, null, 2)).toString('base64'),
        sha: chunkSha,
      }),
    });

    const catalogEntry = {
      id: cleanMovieId,
      title: movieDetail.title,
      year: movieDetail.year,
      poster: movieDetail.artwork.poster,
      fanart: movieDetail.artwork.fanart,
      rating: movieDetail.ratings?.[0]?.value || 7.0,
      original_language: movieDetail.original_language,
      chunk_file: chunkFileName,
      primary_stream_url: primaryStreamUrl,
      available_languages: Array.from(new Set(formattedVersions.map((v: any) => v.language))),
      version_count: formattedVersions.length,
      available_versions: formattedVersions,
    };

    catalogContent.push(catalogEntry);

    await fetch(`https://api.github.com/repos/${REPO_OWNER}/${REPO_NAME}/contents/catalog.json`, {
      method: 'PUT',
      headers,
      body: JSON.stringify({
        message: `Update catalog.json with ${movieDetail.title}`,
        content: Buffer.from(JSON.stringify(catalogContent, null, 2)).toString('base64'),
        sha: catalogData.sha,
      }),
    });

    return NextResponse.json({ success: true, id: cleanMovieId, chunk: chunkFileName });
  } catch (error: any) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}
